const float FREQUENCY      = 0.5;     // 频率 f (Hz)
const float TWO_PI_F_A     = 2.0 * PI * FREQUENCY * AMPLITUDE; // 2πfA

// ==================== 定时器参数 ====================
const long  TIMER_PERIOD_US = 1000;   // 定时器中断周期 (微秒), 1ms

// ==================== 全局变量 ====================
