volatile bool   isRunning   = false;  // 是否运行
volatile bool   btnPressed  = false;  // 按钮按下标志
unsigned long   startTime   = 0;      // 运动开始时间 (ms)
bool            isHomed     = false;  // 是否已复位

// ==================== 初始化 ====================
void setup() {
  Serial.begin(9600);
  Serial.println("=== 滑台简谐运动控制 ===");

  pinMode(STEP_PIN,  OUTPUT);
  pinMode(DIR_PIN,   OUTPUT);
  pinMode(LIMIT_PIN, INPUT_PULLUP);
  pinMode(BTN_PIN,   INPUT_PULLUP);

  digitalWrite(STEP_PIN, LOW);
  digitalWrite(DIR_PIN,  LOW);

  // ① 滑台初始化复位
  homeSlider();

  // ② 滑台移至行程中间位置
  moveToMiddle();

